import{_ as d,C as s,o as l,c as i,E as n,a3 as h,w as c,j as t,a as o}from"./chunks/framework.CCylkYel.js";const g="/screens/devices/delay.png",p="/screens/devices/delay-long.png",S=JSON.parse('{"title":"Delay","description":"","frontmatter":{"title":"Delay","pageClass":"device-doc"},"headers":[],"relativePath":"devices/delay.md","filePath":"devices/delay.md"}'),E={name:"devices/delay.md"};function u(m,e,N,y,D,T){const a=s("DeviceHeading"),r=s("ManualRelated");return l(),i("div",null,[n(a,{slug:"delay",title:"Delay"}),e[1]||(e[1]=h('<p>Delay notes in time</p><p><img src="'+g+'" alt="Delay: SYNCED, DELAY TIME 1/8, 4 echoes, FEEDBACK 60%." class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Echo your notes in time with the tempo, or add a few quiet repeats to thicken a phrase.</p><p><img src="'+p+'" alt="A longer tail: DELAY TIME 1/2, 10 echoes, FEEDBACK 80%." class="screen"></p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Changing <strong>DELAY TIME</strong> moves the echoes already playing: the next one comes one new <strong>DELAY TIME</strong> after the last.</li><li>Changing <strong>SYNC</strong> keeps the echoes going. <strong>DELAY TIME</strong> becomes the nearest note value or milliseconds at the current tempo: <strong>250MS</strong> at 120 BPM is <strong>1/8</strong>.</li><li>On <strong>SYNCED</strong>, a knob or an LFO on <strong>DELAY TIME</strong> steps through <a href="/concepts/mapping#knob-macros">note values</a>.</li><li>Echoes keep playing after you let go of the key. <strong>BYPASS</strong> cuts them.</li></ul><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>BYPASS</td><td>OFF / ON</td><td>ON: MIDI passes through untouched. See <a href="/devices/#bypass">BYPASS</a>.</td></tr><tr><td>SYNC</td><td>FREE / SYNCED</td><td><strong>SYNCED</strong> follows the tempo. <strong>FREE</strong> sets <strong>DELAY TIME</strong> in milliseconds.</td></tr><tr><td>DELAY TIME</td><td>1/64 – 8 BARS, or 10MS – 2000MS</td><td>Time between echoes: a note value with <strong>SYNC</strong> on <strong>SYNCED</strong>, milliseconds on <strong>FREE</strong>.</td></tr><tr><td>INFINITE</td><td>OFF / ON</td><td>ON: echoes keep going past <strong>REPETITIONS</strong>, fading unless <strong>FEEDBACK</strong> is <strong>100%</strong>. Turn it off and the tail plays out and stops.</td></tr><tr><td>REPETITIONS</td><td>0 – 10</td><td>How many echoes play. Not used while <strong>INFINITE</strong> is on.</td></tr><tr><td>FEEDBACK</td><td>0% – 100%</td><td>Level of each echo compared with the one before. <strong>100%</strong> keeps every echo at full level.</td></tr><tr><td>DRY/WET</td><td>0% – 100%</td><td><strong>0%</strong>: only the note you play. <strong>100%</strong>: only the echoes. In between, both get quieter.</td></tr><tr><td>FIXED LENGTH</td><td>OFF / ON</td><td>ON: each echo lasts <strong>NOTE LENGTH</strong>. OFF: each lasts one <strong>DELAY TIME</strong>.</td></tr><tr><td>NOTE LENGTH</td><td>0MS – 1000MS</td><td>How long each echo lasts with <strong>FIXED LENGTH</strong> on.</td></tr><tr><td>OVERDUB</td><td>OFF / ON</td><td>ON: replaying a note that is still echoing starts a new echo line. OFF: it plays only the dry note.</td></tr></tbody></table></div>',9)),n(r,null,{default:c(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"/racks/"},"Racks"),o(" — build a chain of devices")]),t("li",null,[t("a",{href:"/concepts/mapping"},"Mapping"),o(" — put a device setting on a knob or an LFO")]),t("li",null,[t("a",{href:"/concepts/modulation"},"Modulation"),o(" — move a setting while you play")])],-1)])]),_:1})])}const _=d(E,[["render",u]]);export{S as __pageData,_ as default};
